    // gc-clones: work-dir is required; --max-age-days defaults to 30 (the pinned default).
    #[test]
    fn gc_clones_defaults_and_flags() {
        assert_eq!(
            parse(&["prr", "gc-clones", "/w"]),
            Cmd::GcClones {
                work_dirs: s(&["/w"]),
                dry_run: false,
                max_age_days: 30,
            }
        );
        assert_eq!(
            parse(&["prr", "gc-clones", "/w", "--dry-run", "--max-age-days", "7"]),
            Cmd::GcClones {
                work_dirs: s(&["/w"]),
                dry_run: true,
                max_age_days: 7,
            }
        );
        // SEVERAL roots in one sweep: the vetter's stranded `vet-*` clones live in the install dir,
        // not WORK_DIR, so a one-root sweep never reclaimed them.
        assert_eq!(
            parse(&["prr", "gc-clones", "/w", "/install", "--dry-run"]),
            Cmd::GcClones {
                work_dirs: s(&["/w", "/install"]),
                dry_run: true,
                max_age_days: 30,
            }
        );
        // work-dir is mandatory for gc-clones (unlike gc); omitting it is a parse error.
        assert!(Cli::try_parse_from(["prr", "gc-clones"]).is_err());
    }

    // gc: work-dir is OPTIONAL at the parse layer (the required-unless-`--no-clones` rule is enforced
    // in main, after parsing). --max-age-days defaults to 30; --no-clones/--no-nix are bare bools.
    #[test]
    fn gc_workdir_optional_defaults_and_bools() {
        assert_eq!(
            parse(&["prr", "gc", "/w"]),
            Cmd::Gc {
                work_dirs: s(&["/w"]),
                dry_run: false,
                max_age_days: 30,
                no_clones: false,
                no_nix: false,
                nix_threshold: 85,
            }
        );
        // --no-clones with NO work-dir must still parse (main then allows it); this is the parse-layer
        // precondition of the "required unless --no-clones" rule.
        assert_eq!(
            parse(&["prr", "gc", "--no-clones", "--no-nix"]),
            Cmd::Gc {
                work_dirs: vec![],
                dry_run: false,
                max_age_days: 30,
                no_clones: true,
                no_nix: true,
                nix_threshold: 85,
            }
        );
        assert_eq!(
            parse(&[
                "prr",
                "gc",
                "/w",
                "--dry-run",
                "--max-age-days",
                "5",
                "--no-nix"
            ]),
            Cmd::Gc {
                work_dirs: s(&["/w"]),
                dry_run: true,
                max_age_days: 5,
                no_clones: false,
                no_nix: true,
                nix_threshold: 85,
            }
        );
        // --nix-threshold overrides the 85 default.
        assert_eq!(
            parse(&["prr", "gc", "/w", "--nix-threshold", "50"]),
            Cmd::Gc {
                work_dirs: s(&["/w"]),
                dry_run: false,
                max_age_days: 30,
                no_clones: false,
                no_nix: false,
                nix_threshold: 50,
            }
        );
    }

    #[test]
    fn run_metrics_trace() {
        // Bare form is unchanged: the enrichment flags are all optional, so the dashboard's
        // re-derivation from raw traces keeps working untouched.
        assert_eq!(
            parse(&["prr", "run-metrics", "/path/to/trace.jsonl"]),
            Cmd::RunMetrics {
                trace: "/path/to/trace.jsonl".to_string(),
                run_id: None,
                role: None,
                model: None,
                exit_code: None,
                preflight_missing: vec![],
                infra: None,
                skipped: None,
                skip_reason: None,
                forced_run: false,
                forced: vec![],
                force_reason: vec![],
            }
        );
        // The form the runners now use in place of the `| jq '. + {…}'` pipe.
        assert_eq!(
            parse(&[
                "prr",
                "run-metrics",
                "/t.jsonl",
                "--run-id",
                "20260727T100743Z",
                "--role",
                "producer",
                "--model",
                "claude-fable-5",
                "--exit-code",
                "0"
            ]),
            Cmd::RunMetrics {
                trace: "/t.jsonl".to_string(),
                run_id: Some("20260727T100743Z".to_string()),
                role: Some("producer".to_string()),
                model: Some("claude-fable-5".to_string()),
                exit_code: Some(0),
                preflight_missing: vec![],
                infra: None,
                skipped: None,
                skip_reason: None,
                forced_run: false,
                forced: vec![],
                force_reason: vec![],
            }
        );
        // The abort form: `preflight` found nothing to render with, so the model never started.
        assert_eq!(
            parse(&[
                "prr",
                "run-metrics",
                "/t.jsonl",
                "--exit-code",
                "12",
                "--preflight-missing",
                "pdftoppm,pdfinfo"
            ]),
            Cmd::RunMetrics {
                trace: "/t.jsonl".to_string(),
                run_id: None,
                role: None,
                model: None,
                exit_code: Some(12),
                preflight_missing: vec!["pdftoppm".to_string(), "pdfinfo".to_string()],
                infra: None,
                skipped: None,
                skip_reason: None,
                forced_run: false,
                forced: vec![],
                force_reason: vec![],
            }
        );
        // The SKIP form (#160): the usage-gate paused the tick, the runners record the row with
        // the gate's own line, verbatim.
        assert_eq!(
            parse(&[
                "prr",
                "run-metrics",
                "/t.jsonl",
                "--run-id",
                "20260731T090001Z",
                "--role",
                "producer",
                "--model",
                "claude-fable-5",
                "--exit-code",
                "10",
                "--skipped",
                "usage-gate",
                "--skip-reason",
                "PAUSE: 91% of the weekly budget used (endpoint) — at/over the 90% ceiling"
            ]),
            Cmd::RunMetrics {
                trace: "/t.jsonl".to_string(),
                run_id: Some("20260731T090001Z".to_string()),
                role: Some("producer".to_string()),
                model: Some("claude-fable-5".to_string()),
                exit_code: Some(10),
                preflight_missing: vec![],
                infra: None,
                skipped: Some("usage-gate".to_string()),
                skip_reason: Some(
                    "PAUSE: 91% of the weekly budget used (endpoint) — at/over the 90% ceiling"
                        .to_string()
                ),
                forced_run: false,
                forced: vec![],
                force_reason: vec![],
            }
        );
        // The two skip flags arrive together or not at all: a gate with no reason would emit a
        // row that cannot say WHY the tick paused, and a reason with no gate has no field to
        // hang it on. Refused at parse, so no runner edit can half-supply the pair.
        assert!(
            Cli::try_parse_from(["prr", "run-metrics", "/t.jsonl", "--skipped", "usage-gate"])
                .is_err(),
            "--skipped without --skip-reason must be refused"
        );
        assert!(
            Cli::try_parse_from([
                "prr",
                "run-metrics",
                "/t.jsonl",
                "--skip-reason",
                "PAUSE: x"
            ])
            .is_err(),
            "--skip-reason without --skipped must be refused"
        );
        // The FORCE form (#245): a human ran this tick past the gate's PAUSE on purpose, so the row
        // must say so rather than presenting itself as one the schedule produced.
        assert_eq!(
            parse(&[
                "prr",
                "run-metrics",
                "/t.jsonl",
                "--run-id",
                "20260731T090001Z",
                "--role",
                "producer",
                "--model",
                "claude-fable-5",
                "--exit-code",
                "0",
                "--forced-run",
                "--forced",
                "disabled",
                "--force-reason",
                "DISABLED flag present",
                "--forced",
                "usage-gate",
                "--force-reason",
                "PAUSE: 91% of the weekly budget used (endpoint) — at/over the 90% ceiling"
            ]),
            Cmd::RunMetrics {
                trace: "/t.jsonl".to_string(),
                run_id: Some("20260731T090001Z".to_string()),
                role: Some("producer".to_string()),
                model: Some("claude-fable-5".to_string()),
                exit_code: Some(0),
                preflight_missing: vec![],
                infra: None,
                skipped: None,
                skip_reason: None,
                forced_run: true,
                forced: vec!["disabled".to_string(), "usage-gate".to_string()],
                force_reason: vec![
                    "DISABLED flag present".to_string(),
                    "PAUSE: 91% of the weekly budget used (endpoint) — at/over the 90% ceiling"
                        .to_string(),
                ],
            }
        );
        // The ORDINARY forced run: a human started it and nothing was in the way. It still parses,
        // and still says the schedule did not start it — which is what `--forced-run` carries on
        // its own. Lose this case and the marker comes to mean "something blocked me" instead of
        // "a human started me".
        assert_eq!(
            parse(&["prr", "run-metrics", "/t.jsonl", "--forced-run"]),
            Cmd::RunMetrics {
                trace: "/t.jsonl".to_string(),
                run_id: None,
                role: None,
                model: None,
                exit_code: None,
                preflight_missing: vec![],
                infra: None,
                skipped: None,
                skip_reason: None,
                forced_run: true,
                forced: vec![],
                force_reason: vec![],
            }
        );
        // An override with nothing to be an override OF: refused at parse, so a runner edit that
        // dropped `--forced-run` fails loudly rather than writing a row that reads as scheduled
        // while naming stops it walked past.
        assert!(
            Cli::try_parse_from([
                "prr",
                "run-metrics",
                "/t.jsonl",
                "--forced",
                "usage-gate",
                "--force-reason",
                "PAUSE: x"
            ])
            .is_err(),
            "--forced and --force-reason without --forced-run must be refused"
        );
        // EACH flag carries its own `requires`. Asserted separately because the pair above is
        // refused as long as EITHER one does — so deleting `forced`'s requirement would leave that
        // assertion passing while `--forced` alone silently parsed into a row nothing marks.
        assert!(
            Cli::try_parse_from(["prr", "run-metrics", "/t.jsonl", "--forced", "usage-gate"])
                .is_err(),
            "--forced alone must be refused"
        );
        assert!(
            Cli::try_parse_from([
                "prr",
                "run-metrics",
                "/t.jsonl",
                "--force-reason",
                "PAUSE: x"
            ])
            .is_err(),
            "--force-reason without --forced-run must be refused"
        );
        // SKIPPED and FORCED are opposites — a tick the pipeline declined to run against one it was
        // told to run anyway — so a row can never be both. Refused at parse, where a runner edit
        // that tried to emit both fails loudly instead of writing a row no consumer can read.
        assert!(
            Cli::try_parse_from([
                "prr",
                "run-metrics",
                "/t.jsonl",
                "--skipped",
                "usage-gate",
                "--skip-reason",
                "PAUSE: x",
                "--forced-run"
            ])
            .is_err(),
            "a row cannot be both skipped and forced"
        );
    }

